'use strict';
/**
 * registry-top1.test.js — the registry-derived top-1 retrieval gate over the cases
 * generated by evals/retrieval/gen-registry-top1.js, judged by
 * evals/retrieval/registry-gate.js.
 *
 * The skill package ships as a standalone zip of this directory tree
 * (references/ + scripts/), without the repo-root evals/ directory. Only there
 * (tests/repo-context.js, which recognises the package by the absence of every
 * repository marker) does this file skip. In the repository every gate file is
 * required: registry-top1.json, registry-gate.js, registry-top1-losses.json and
 * the gated question set (lib.js CURRENT_QUESTIONS). A missing one fails, as do an empty case list and a case
 * list with no dev case, so dropping a file from a commit cannot turn the gate off.
 *
 * The cases are provenance labels, not ground truth, so the gate is NET and follows the
 * gated question set's lesson split (lib.js CURRENT_QUESTIONS): on cases whose
 * expected lesson is a DEV lesson, no net loss against the recorded `passes_today`, and
 * every lost case is in the named-loss list (evals/retrieval/registry-top1-losses.json,
 * one reason each; a stale entry fails). Cases whose lesson is a HOLDOUT lesson are
 * printed (lost and gained, by name), never gated. Recorded misses that still miss are
 * counted, not asserted.
 */
const test = require('node:test');
const assert = require('node:assert');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { execFileSync } = require('node:child_process');

const { REPO_ROOT, IN_REPO, STANDALONE_SKIP, currentEvalFiles } = require('./repo-context.js');

const EVALS = path.join(REPO_ROOT, 'evals', 'retrieval');
const DATA_PATH = path.join(EVALS, 'registry-top1.json');
const LOSSES_PATH = path.join(EVALS, 'registry-top1-losses.json');
// The lesson split the gate follows: the gated question set (evals/retrieval/lib.js
// CURRENT_QUESTIONS). Resolved only in the repository; the package has no evals/.
const QUESTIONS_PATH = IN_REPO ? currentEvalFiles().questions : path.join(EVALS, 'questions.json');
const GATE_PATH = path.join(EVALS, 'registry-gate.js');
const SEARCH_JS = path.join(__dirname, '..', 'search.js');
const GATE_FILES = [DATA_PATH, LOSSES_PATH, QUESTIONS_PATH, GATE_PATH];

/**
 * Load and validate the gate's inputs. Throws (never skips) on a missing file, a
 * missing split, an empty case list or one without a dev case.
 */
function loadGate(files = { data: DATA_PATH, losses: LOSSES_PATH, questions: QUESTIONS_PATH, gate: GATE_PATH }) {
  const missing = Object.values(files).filter((f) => !fs.existsSync(f));
  if (missing.length) throw new Error(`registry gate file(s) missing in a repository checkout: ${missing.map((f) => path.relative(REPO_ROOT, f)).join(', ')}`);
  const { judge } = require(files.gate);
  const data = JSON.parse(fs.readFileSync(files.data, 'utf8'));
  if (!Array.isArray(data.cases) || !data.cases.length) throw new Error('registry-top1.json must have a nonempty cases array');
  const { split } = JSON.parse(fs.readFileSync(files.questions, 'utf8'));
  if (!split || !Array.isArray(split.dev) || !Array.isArray(split.holdout)) throw new Error(`${path.basename(files.questions)} must carry the lesson split`);
  const holdout = new Set(split.holdout);
  if (!data.cases.some((c) => !holdout.has(c.expected_id))) throw new Error('registry-top1.json has no dev case: the gate would judge nothing');
  const { losses } = JSON.parse(fs.readFileSync(files.losses, 'utf8'));
  if (!Array.isArray(losses)) throw new Error('registry-top1-losses.json must have a losses array');
  return { judge, data, split, losses };
}

test('registry gate: skipped only in the shipped package; in the repository every gate file is present', (t) => {
  if (!IN_REPO) { t.skip(STANDALONE_SKIP); return; }
  for (const f of GATE_FILES) assert.ok(fs.existsSync(f), `${path.relative(REPO_ROOT, f)} is missing`);
});

test('registry gate inputs: a missing file, an empty case list or no dev case fails instead of skipping', (t) => {
  if (!IN_REPO) { t.skip(STANDALONE_SKIP); return; }
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'cci-registry-gate-'));
  t.after(() => fs.rmSync(dir, { recursive: true, force: true }));
  const files = { data: path.join(dir, 'registry-top1.json'), losses: path.join(dir, 'losses.json'), questions: path.join(dir, 'questions.json'), gate: GATE_PATH };
  const write = (f, obj) => fs.writeFileSync(f, JSON.stringify(obj));
  write(files.questions, { split: { dev: [1], holdout: [7] } });
  write(files.losses, { losses: [] });
  write(files.data, { cases: [{ name: 'a', expected_id: 1, passes_today: true }] });
  assert.strictEqual(loadGate(files).data.cases.length, 1, 'control: a valid set loads');
  assert.throws(() => loadGate({ ...files, gate: path.join(dir, 'registry-gate.js') }), /missing in a repository checkout: .*registry-gate\.js/);
  assert.throws(() => loadGate({ ...files, losses: path.join(dir, 'nope.json') }), /missing/);
  write(files.data, { cases: [] });
  assert.throws(() => loadGate(files), /nonempty cases array/);
  write(files.data, {});
  assert.throws(() => loadGate(files), /nonempty cases array/);
  write(files.data, { cases: [{ name: 'h', expected_id: 7, passes_today: true }] });
  assert.throws(() => loadGate(files), /no dev case/);
  write(files.data, { cases: [{ name: 'a', expected_id: 1, passes_today: true }] });
  write(files.questions, { cases: [] });
  assert.throws(() => loadGate(files), /lesson split/);
});

test('registry-top1.json was generated under the current lesson split', (t) => {
  if (!IN_REPO) { t.skip(STANDALONE_SKIP); return; }
  const { data, split } = loadGate();
  const holdout = new Set(split.holdout);
  const stale = data.cases.filter((c) => c.split !== (holdout.has(c.expected_id) ? 'holdout' : 'dev'));
  assert.deepStrictEqual(stale.map((c) => `${c.name} (L${c.expected_id}: recorded ${c.split})`), [],
    `these cases record a split other than ${path.basename(QUESTIONS_PATH)}'s: regenerate with node evals/retrieval/gen-registry-top1.js`);
  const { splitHash } = require(path.join(EVALS, 'lib.js'));
  assert.strictEqual(data.split_sha256, splitHash(split), 'split_sha256 is not the current split\'s');
});

test('registry gate rules: net on dev, named losses, stale entries, holdout reported only', (t) => {
  if (!IN_REPO) { t.skip(STANDALONE_SKIP); return; }
  const { judge } = loadGate();
  const split = { dev: [1, 2, 3], holdout: [7, 8] };
  const cases = [
    { name: 'a', expected_id: 1, passes_today: true },
    { name: 'b', expected_id: 2, passes_today: false },
    { name: 'c', expected_id: 3, passes_today: true },
    { name: 'h', expected_id: 7, passes_today: true },
  ];
  const tops = (m) => (c) => (c.name in m ? m[c.name] : c.expected_id);
  // everything as recorded (b still misses): clean
  assert.deepStrictEqual(judge(cases, split, [], tops({ b: 9 })).failures, []);
  // a dev loss not named fails; named with the right lesson it passes (net 0: b gained)
  const lost = tops({ a: 5 });
  assert.match(judge(cases, split, [], lost).failures.join('\n'), /"a": expected L1 at rank 1, got L5 — not in the named-loss list/);
  assert.deepStrictEqual(judge(cases, split, [{ name: 'a', lost_to: 5, reason: 'r' }], lost).failures, []);
  // named but lost to another lesson; no reason
  assert.match(judge(cases, split, [{ name: 'a', lost_to: 6, reason: 'r' }], lost).failures.join('\n'), /records a loss to L6, now L5/);
  assert.match(judge(cases, split, [{ name: 'a', lost_to: 5 }], lost).failures.join('\n'), /has no reason/);
  // a net loss fails even when every loss is named
  const two = tops({ a: 5, c: 5, b: 9 });
  const r = judge(cases, split, [{ name: 'a', lost_to: 5, reason: 'r' }, { name: 'c', lost_to: 5, reason: 'r' }], two);
  assert.match(r.failures.join('\n'), /net loss \(0 gained, 2 lost\)/);
  // stale, unknown and holdout entries fail
  const f = judge(cases, split, [{ name: 'c', lost_to: 5, reason: 'r' }, { name: 'zz', lost_to: 1, reason: 'r' }, { name: 'h', lost_to: 1, reason: 'r' }], tops({ b: 9 })).failures.join('\n');
  assert.match(f, /"c" is stale/);
  assert.match(f, /"zz" names no registry case/);
  assert.match(f, /"h" is a holdout case/);
  // a holdout loss is reported, never a failure
  const h = judge(cases, split, [], tops({ b: 9, h: 1 }));
  assert.deepStrictEqual(h.failures, []);
  assert.deepStrictEqual(h.holdout.lost.map((x) => x.name), ['h']);
  // nothing to judge is a failure, not a pass
  assert.match(judge([], split, [], () => null).failures.join('\n'), /no dev registry cases/);
  assert.match(judge([cases[3]], split, [], tops({})).failures.join('\n'), /no dev registry cases/);
});

test('repo-context: the shipped package layout skips, any repository marker does not', (t) => {
  const { isRepoCheckout } = require('./repo-context.js');
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'cci-repo-context-'));
  t.after(() => fs.rmSync(dir, { recursive: true, force: true }));
  // the zip: <x>/claude-code-internals, nothing above it
  const zip = path.join(dir, 'unzipped', 'a', 'b', 'claude-code-internals');
  fs.mkdirSync(zip, { recursive: true });
  assert.strictEqual(isRepoCheckout(zip), false);
  // check-clean.sh's copy: skill-package/ layout, evals/, no .git
  const copy = path.join(dir, 'copy', 'skill-package', 'skills', 'claude-code-internals');
  fs.mkdirSync(copy, { recursive: true });
  assert.strictEqual(isRepoCheckout(copy), true, 'the skill-package/ level alone marks the repository');
  // either other marker alone
  const bare = path.join(dir, 'bare', 'x', 'skills', 'claude-code-internals');
  fs.mkdirSync(bare, { recursive: true });
  assert.strictEqual(isRepoCheckout(bare), false);
  fs.mkdirSync(path.join(dir, 'bare', 'evals'));
  assert.strictEqual(isRepoCheckout(bare), true, 'evals/ marks the repository');
  fs.rmSync(path.join(dir, 'bare', 'evals'), { recursive: true });
  fs.writeFileSync(path.join(dir, 'bare', '.git'), 'gitdir: elsewhere\n');
  assert.strictEqual(isRepoCheckout(bare), true, '.git (a worktree file) marks the repository');
  // and this run is in the repository
  assert.strictEqual(isRepoCheckout(), true);
});

test('registry-derived top-1 cases (evals/retrieval/registry-top1.json), judged net on dev lessons', (t) => {
  if (!IN_REPO) { t.skip(STANDALONE_SKIP); return; }
  const { judge, data, split, losses } = loadGate();

  // A private index cache for this run: hundreds of spawns share one build, and the
  // user's own cache directory is never written by tests.
  const cacheDir = fs.mkdtempSync(path.join(os.tmpdir(), 'cci-registry-top1-cache-'));
  t.after(() => fs.rmSync(cacheDir, { recursive: true, force: true }));
  const env = { ...process.env, CCI_INDEX_CACHE_DIR: cacheDir };
  delete env.CCI_NO_INDEX_CACHE;
  const topOf = (c) => {
    try {
      const results = JSON.parse(execFileSync('node', [SEARCH_JS, c.name, '--json', '--top=1'], { encoding: 'utf8', env }));
      return results[0] ? results[0].id : null;
    } catch (err) {
      return null; // a miss (stop-words-only or a hard failure)
    }
  };

  const r = judge(data.cases, split, losses, topOf);
  const known = data.cases.filter((c) => !c.passes_today).length;
  const list = (xs) => xs.map((x) => `"${x.name}" (L${x.expected_id} -> ${x.top === null ? 'none' : 'L' + x.top})`).join(', ') || 'none';
  console.log(`registry-top1: ${data.cases.length} cases (${known} recorded misses), generated from commit ${data.generated_from_commit || 'unknown'}`);
  console.log(`  dev lessons: ${r.dev.n} cases, gained ${r.dev.gained.length}, lost ${r.dev.lost.length}, net ${r.dev.net}; named losses ${losses.length}`);
  console.log(`    lost: ${list(r.dev.lost)}`);
  console.log(`  holdout lessons (reported, not gated): ${r.holdout.n} cases, gained ${r.holdout.gained.length}, lost ${r.holdout.lost.length}, net ${r.holdout.net}`);
  console.log(`    lost: ${list(r.holdout.lost)}`);

  assert.deepStrictEqual(r.failures, [], `${r.failures.length} failure(s):\n  ${r.failures.join('\n  ')}`);
});
